<script lang="ts">
import { defineComponent } from 'vue';
import { deleteFont, getFontUrl, listFonts, uploadFont, type Font } from '../../api/reader';
import { localeFromValue, setLocale } from '../../i18n';
import { supportedLocales } from '../../i18n/locales';
import AppButton from '../../ui/components/AppButton.vue';
import FeatureScaffold from '../../ui/components/FeatureScaffold.vue';
import { defaultReaderPreferences, loadReaderPreferences, saveReaderPreferences, type ReaderPreferences } from '../reader/reader-preferences';
import { availablePreferenceFont, fontNameFromFile, formatFileSize, preferencesAfterFontDeletion, validateFontFile } from './font-settings';

export default defineComponent({
  name:'SettingsView',components:{AppButton,FeatureScaffold},
  data(){return{locales:supportedLocales,fonts:[] as Font[],preferences:loadReaderPreferences(),loading:true,error:'',notice:'',uploading:false,uploadError:'',pendingDelete:null as Font|null,deleting:false}},
  computed:{selectedLocale:{get():string{return String(this.$i18n.locale)},async set(value:string){await setLocale(localeFromValue(value))}},readerStyle():Record<string,string>{return{'--preview-bg':this.preferences.background,'--preview-text':this.preferences.textColor,'--preview-size':`${this.preferences.fontSize}px`,'--preview-line':String(this.preferences.lineHeight),'--preview-weight':String(this.preferences.fontWeight),'--preview-width':`${this.preferences.pageWidth}px`,'--preview-font':this.preferences.fontId==='system'?'var(--font-literary)':`settings-font-${this.preferences.fontId}, var(--font-literary)`}}},
  watch:{preferences:{deep:true,handler(value:ReaderPreferences){saveReaderPreferences(value)}}},
  async mounted(){await this.loadFonts()},
  methods:{
    async loadFonts(){this.loading=true;this.error='';try{this.fonts=await listFonts();const next=availablePreferenceFont(this.preferences,this.fonts);if(next!==this.preferences)this.preferences=next;for(const font of this.fonts)this.installFont(font)}catch(cause){this.error=cause instanceof Error?cause.message:this.$t('settings.fonts.loadFailed')}finally{this.loading=false}},
    installFont(font:Font){if(typeof FontFace==='undefined')return;const face=new FontFace(`settings-font-${font.id}`,`url(${getFontUrl(font.id)})`);void face.load().then(loaded=>document.fonts.add(loaded)).catch(()=>undefined)},
    updatePreference(key:keyof ReaderPreferences,value:string|number){this.preferences={...this.preferences,[key]:typeof this.preferences[key]==='number'?Number(value):value}},
    preset(background:string,textColor:string){this.preferences={...this.preferences,background,textColor}},
    resetReaderDefaults(){this.preferences={...defaultReaderPreferences};this.notice=this.$t('settings.reader.resetDone')},
    async chooseFont(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file)return;const validation=validateFontFile(file);if(validation!=='ok'){this.uploadError=this.$t(`settings.fonts.validation.${validation}`);return}this.uploading=true;this.uploadError='';this.notice='';try{const font=await uploadFont(file,fontNameFromFile(file.name));this.fonts=[font,...this.fonts.filter(item=>item.id!==font.id)];this.installFont(font);this.notice=this.$t('settings.fonts.uploaded',{name:font.name})}catch(cause){this.uploadError=cause instanceof Error?cause.message:this.$t('settings.fonts.uploadFailed')}finally{this.uploading=false}},
    async confirmDelete(){if(!this.pendingDelete||this.deleting)return;this.deleting=true;this.error='';const font=this.pendingDelete;try{await deleteFont(font.id);this.fonts=this.fonts.filter(item=>item.id!==font.id);this.preferences=preferencesAfterFontDeletion(this.preferences,font.id);this.notice=this.$t('settings.fonts.deleted',{name:font.name});this.pendingDelete=null}catch(cause){this.error=cause instanceof Error?cause.message:this.$t('settings.fonts.deleteFailed')}finally{this.deleting=false}},
    size(bytes:number){return formatFileSize(bytes)},
  }
});
</script>
<template><FeatureScaffold :title="$t('settings.title')" :description="$t('settings.description')"><div class="settings"><section class="panel language"><div><p class="eyebrow">{{ $t('settings.language.eyebrow') }}</p><h2>{{ $t('settings.language.title') }}</h2><p>{{ $t('settings.language.description') }}</p></div><label><span>{{ $t('settings.language.label') }}</span><select v-model="selectedLocale"><option v-for="locale in locales" :key="locale.code" :value="locale.code">{{ locale.label }}</option></select></label></section><section class="panel fonts"><header><div><p class="eyebrow">{{ $t('settings.fonts.eyebrow') }}</p><h2>{{ $t('settings.fonts.title') }}</h2><p>{{ $t('settings.fonts.description') }}</p></div><label class="upload"><span>{{ uploading?$t('settings.fonts.uploading'):$t('settings.fonts.upload') }}</span><input type="file" accept=".ttf,.otf,.woff,.woff2,font/ttf,font/otf,font/woff,font/woff2" :disabled="uploading" @change="chooseFont"></label></header><p v-if="uploadError" class="error" role="alert">{{ uploadError }}</p><p v-if="loading" aria-busy="true">{{ $t('settings.fonts.loading') }}</p><p v-else-if="!fonts.length" class="empty">{{ $t('settings.fonts.empty') }}</p><ul v-else><li v-for="font in fonts" :key="font.id"><div class="font-identity"><strong>{{ font.name }}</strong><small>{{ size(font.fileSize) }}</small></div><span class="sample" :style="{fontFamily:`settings-font-${font.id}, var(--font-literary)`}">Aa 你好 閱讀</span><AppButton variant="danger" @click="pendingDelete=font">{{ $t('settings.fonts.delete') }}</AppButton></li></ul></section><section class="panel reader-defaults"><header><div><p class="eyebrow">{{ $t('settings.reader.eyebrow') }}</p><h2>{{ $t('settings.reader.title') }}</h2><p>{{ $t('settings.reader.description') }}</p></div><AppButton variant="quiet" @click="resetReaderDefaults">{{ $t('settings.reader.reset') }}</AppButton></header><div class="reader-grid"><div class="controls"><label>{{ $t('reader.settings.fontSize') }}<span><input type="range" min="14" max="32" :value="preferences.fontSize" @input="updatePreference('fontSize',($event.target as HTMLInputElement).value)"><output>{{ preferences.fontSize }}px</output></span></label><label>{{ $t('reader.settings.lineHeight') }}<span><input type="range" min="1.3" max="2.5" step=".05" :value="preferences.lineHeight" @input="updatePreference('lineHeight',($event.target as HTMLInputElement).value)"><output>{{ preferences.lineHeight.toFixed(2) }}</output></span></label><label>{{ $t('reader.settings.pageWidth') }}<span><input type="range" min="480" max="1000" step="20" :value="preferences.pageWidth" @input="updatePreference('pageWidth',($event.target as HTMLInputElement).value)"><output>{{ preferences.pageWidth }}px</output></span></label><label>{{ $t('reader.settings.weight') }}<select :value="preferences.fontWeight" @change="updatePreference('fontWeight',($event.target as HTMLSelectElement).value)"><option value="300">300</option><option value="400">400</option><option value="500">500</option><option value="700">700</option></select></label><label>{{ $t('reader.settings.font') }}<select :value="preferences.fontId" @change="updatePreference('fontId',($event.target as HTMLSelectElement).value)"><option value="system">{{ $t('reader.settings.systemFont') }}</option><option v-for="font in fonts" :key="font.id" :value="font.id">{{ font.name }}</option></select></label><div class="colors"><label>{{ $t('reader.settings.background') }}<input type="color" :value="preferences.background" @input="updatePreference('background',($event.target as HTMLInputElement).value)"></label><label>{{ $t('reader.settings.text') }}<input type="color" :value="preferences.textColor" @input="updatePreference('textColor',($event.target as HTMLInputElement).value)"></label></div><div class="presets"><button type="button" @click="preset('#f4eedc','#24333a')">{{ $t('reader.settings.sepia') }}</button><button type="button" @click="preset('#fffaf0','#24333a')">{{ $t('reader.settings.light') }}</button><button type="button" @click="preset('#20272a','#e8e1d2')">{{ $t('reader.settings.dark') }}</button></div></div><article class="preview" :style="readerStyle"><small>{{ $t('settings.reader.previewLabel') }}</small><h3>{{ $t('settings.reader.previewTitle') }}</h3><p>{{ $t('settings.reader.previewText') }}</p></article></div></section><p v-if="notice" class="notice" role="status">{{ notice }}</p><p v-if="error" class="error" role="alert">{{ error }}</p></div><div v-if="pendingDelete" class="overlay" @click.self="pendingDelete=null"><section class="confirmation" role="alertdialog" :aria-label="$t('settings.fonts.deleteTitle')"><h2>{{ $t('settings.fonts.deleteTitle') }}</h2><p>{{ $t('settings.fonts.deleteDescription',{name:pendingDelete.name}) }}</p><div><AppButton variant="secondary" :disabled="deleting" @click="pendingDelete=null">{{ $t('settings.cancel') }}</AppButton><AppButton variant="danger" :busy="deleting" @click="confirmDelete">{{ $t('settings.fonts.confirmDelete') }}</AppButton></div></section></div></FeatureScaffold></template>
<style scoped>.settings{display:grid;gap:1rem}.panel{padding:1rem;border:1px solid var(--color-border);border-radius:var(--radius-lg);background:var(--color-paper-raised)}.panel>header,.language{display:flex;justify-content:space-between;align-items:center;gap:1.5rem}.panel h2{margin:.15rem 0;font:700 1.25rem var(--font-literary)}.panel p{margin:.25rem 0 0;color:var(--color-ink-muted);line-height:1.55}.eyebrow{color:var(--color-warm)!important;font-size:.7rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase}.language label{min-width:min(20rem,45%);display:grid;gap:.3rem}.language label span{color:var(--color-ink-muted);font-size:.78rem;font-weight:700}select{min-height:2.75rem;border:1px solid var(--color-border);border-radius:var(--radius-md);padding:.55rem .7rem;background:white;color:var(--color-ink)}.upload{min-height:2.75rem;display:inline-flex;align-items:center;border-radius:var(--radius-md);padding:.65rem 1rem;background:var(--color-accent);color:white;font-weight:700;cursor:pointer}.upload input{position:absolute;width:1px;height:1px;opacity:0}.fonts ul{list-style:none;display:grid;gap:.55rem;margin:1rem 0 0;padding:0}.fonts li{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:1rem;align-items:center;padding:.75rem;border:1px solid var(--color-border);border-radius:var(--radius-md)}.font-identity{min-width:0;display:grid}.font-identity strong,.font-identity small{overflow-wrap:anywhere}.font-identity small{color:var(--color-ink-muted)}.sample{min-width:8rem;padding:.5rem;border-radius:var(--radius-sm);background:var(--color-paper-muted);text-align:center;font-size:1.05rem}.empty{padding:1rem;text-align:center}.reader-grid{display:grid;grid-template-columns:minmax(18rem,.8fr) minmax(20rem,1.2fr);gap:1.25rem;margin-top:1rem}.controls{display:grid;gap:.8rem}.controls>label{display:grid;gap:.35rem;font-size:.8rem;font-weight:700}.controls>label>span{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:.6rem;align-items:center}.colors,.presets{display:flex;flex-wrap:wrap;gap:.6rem}.colors label{display:flex;align-items:center;gap:.4rem}.presets button{min-height:2.75rem;border:1px solid var(--color-border);border-radius:var(--radius-md);padding:.55rem .75rem;background:var(--color-paper-muted);color:var(--color-ink)}.preview{width:min(100%,var(--preview-width));min-height:18rem;align-self:start;justify-self:center;padding:clamp(1.25rem,4vw,2.5rem);border-radius:var(--radius-lg);background:var(--preview-bg);color:var(--preview-text);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--preview-text) 12%,transparent);font:var(--preview-weight) var(--preview-size)/var(--preview-line) var(--preview-font)}.preview small{font-family:var(--font-ui);font-size:.7rem;opacity:.65}.preview h3{margin:1rem 0;text-align:center;font-size:1.35em}.preview p{color:inherit;text-align:justify}.notice,.error{margin:0;padding:.7rem;border-radius:var(--radius-md)}.notice{background:#e7efe8;color:var(--color-success)}.error{background:#f8e4df;color:var(--color-danger)}.overlay{position:fixed;z-index:90;inset:0;display:grid;place-items:center;padding:1rem;background:rgb(0 0 0/.42)}.confirmation{width:min(30rem,100%);padding:1rem;border-radius:var(--radius-lg);background:var(--color-paper-raised)}.confirmation h2{font:700 1.2rem var(--font-literary)}.confirmation p{color:var(--color-ink-muted)}.confirmation div{display:flex;justify-content:flex-end;gap:.5rem;margin-top:1rem}@media(max-width:48rem){.reader-grid{grid-template-columns:1fr}.preview{min-height:14rem}.fonts li{grid-template-columns:minmax(0,1fr) auto}.sample{grid-column:1/2;grid-row:2}.fonts li :deep(.app-button){grid-column:2;grid-row:1/3}}@media(max-width:36rem){.panel>header,.language{align-items:stretch;flex-direction:column}.language label{width:100%;min-width:0}.upload{justify-content:center}.fonts li{grid-template-columns:1fr}.sample,.fonts li :deep(.app-button){grid-column:auto;grid-row:auto}.fonts li :deep(.app-button){width:100%}.overlay{align-items:end;padding:0}.confirmation{border-radius:var(--radius-lg) var(--radius-lg) 0 0}}</style>
